// Valida el CSV completo antes de tocar la base: si hay un solo error, no se carga nada.
const COLUMNAS = ['cobro_id', 'inmueble', 'fecha_cobro', 'importe'];
const filas = $input.all().map((item) => item.json);
if (filas.length === 0) throw new Error('El CSV no contiene filas de datos');

const errores = [];
const vistos = new Set();
const lote = [];
filas.forEach((fila, idx) => {
  const linea = idx + 2; // la linea 1 es la cabecera
  const claves = Object.keys(fila);
  const faltan = COLUMNAS.filter((c) => !claves.includes(c));
  const sobran = claves.filter((c) => !COLUMNAS.includes(c));
  if (faltan.length || sobran.length) {
    errores.push(`linea ${linea}: columnas incorrectas (faltan: ${faltan.join('|') || '-'}; sobran: ${sobran.join('|') || '-'})`);
    return;
  }
  const v = Object.fromEntries(COLUMNAS.map((c) => [c, String(fila[c] ?? '').trim()]));

  if (!/^[A-Za-z0-9][A-Za-z0-9_-]{0,19}$/.test(v.cobro_id)) errores.push(`linea ${linea}: cobro_id vacio o no valido`);
  else if (vistos.has(v.cobro_id)) errores.push(`linea ${linea}: cobro_id repetido ${v.cobro_id}`);
  vistos.add(v.cobro_id);

  if (!v.inmueble || v.inmueble.length > 100) errores.push(`linea ${linea}: inmueble vacio o de mas de 100 caracteres`);

  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(v.fecha_cobro);
  const d = m ? new Date(Date.UTC(+m[1], +m[2] - 1, +m[3])) : null;
  if (!m || d.getUTCFullYear() !== +m[1] || d.getUTCMonth() !== +m[2] - 1 || d.getUTCDate() !== +m[3]) {
    errores.push(`linea ${linea}: fecha_cobro debe ser una fecha ISO AAAA-MM-DD valida`);
  }

  if (!/^\d{1,10}(\.\d{1,2})?$/.test(v.importe) || Number(v.importe) <= 0) {
    errores.push(`linea ${linea}: importe debe ser positivo, con punto decimal y hasta 2 decimales`);
  }
  lote.push(v);
});

if (errores.length) {
  throw new Error(`CSV no valido (${errores.length} error/es): ${errores.slice(0, 20).join('; ')}`);
}

const totalCentimos = lote.reduce((s, f) => s + Math.round(Number(f.importe) * 100), 0);
return [{ json: { filas: lote.length, total_csv: (totalCentimos / 100).toFixed(2), lote: JSON.stringify(lote) } }];

