-- Upsert atomico por cobro_id. El lote validado llega como unico parametro (@p1) y se desempaqueta con OPENJSON.
SET XACT_ABORT ON;
DECLARE @lote NVARCHAR(MAX) = $1;
DECLARE @acciones TABLE (accion NVARCHAR(10) NOT NULL);

BEGIN TRAN;
MERGE dbo.cobros WITH (HOLDLOCK) AS t
USING (
    SELECT j.cobro_id,
           j.inmueble,
           CONVERT(date, j.fecha_cobro, 23)     AS fecha_cobro,
           CAST(j.importe AS DECIMAL(12, 2))    AS importe
    FROM OPENJSON(@lote) WITH (
        cobro_id    NVARCHAR(20)  '$.cobro_id',
        inmueble    NVARCHAR(100) '$.inmueble',
        fecha_cobro CHAR(10)      '$.fecha_cobro',
        importe     VARCHAR(20)   '$.importe'
    ) AS j
) AS s
ON t.cobro_id = s.cobro_id
WHEN MATCHED AND (t.inmueble <> s.inmueble OR t.fecha_cobro <> s.fecha_cobro OR t.importe <> s.importe) THEN
    UPDATE SET inmueble = s.inmueble, fecha_cobro = s.fecha_cobro, importe = s.importe, actualizado_en = SYSDATETIME()
WHEN NOT MATCHED BY TARGET THEN
    INSERT (cobro_id, inmueble, fecha_cobro, importe) VALUES (s.cobro_id, s.inmueble, s.fecha_cobro, s.importe)
OUTPUT $action INTO @acciones;
COMMIT;

SELECT (SELECT COUNT(*) FROM OPENJSON(@lote))                     AS filas_csv,
       ISNULL(SUM(CASE WHEN accion = 'INSERT' THEN 1 ELSE 0 END), 0) AS insertadas,
       ISNULL(SUM(CASE WHEN accion = 'UPDATE' THEN 1 ELSE 0 END), 0) AS actualizadas
FROM @acciones;
